INSERT INTO "ledger_accounts" ("id","companyId","code","name","accountClass","normalBalance","systemKey","isSystem","allowPosting","isActive","createdAt","updatedAt") SELECT gen_random_uuid(),c."id",'5050','Project Material Cost','EXPENSE'::"LedgerAccountClass",'DEBIT'::"NormalBalanceSide",'PROJECT_MATERIAL_COST',true,true,true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM "companies" c WHERE NOT EXISTS(SELECT 1 FROM "ledger_accounts" a WHERE a."companyId"=c."id" AND a."systemKey"='PROJECT_MATERIAL_COST');
